print(f'SHA-256: {EXPECTED_SHA256}')

import ast

# Verify the agent parses and has the expected entry point
tree = ast.parse(source_bytes.decode('utf-8', errors='replace'))
functions = [node.name for node in ast.walk(tree) if isinstance(node, ast.FunctionDef)]
assert 'agent' in functions, 'No agent() function found'
print(f'Entry point verified: agent() found among {len(functions)} functions')
print(f'Source lines: {source_bytes.count(b"\n") + 1:,}')

import gzip as gzip_mod, io, tarfile
from IPython.display import FileLink, display

ARCHIVE = WORKDIR / 'submission.tar.gz'

with ARCHIVE.open('wb') as f:
    with gzip_mod.GzipFile(filename='', mode='wb', fileobj=f, mtime=0) as compressed:
        with tarfile.open(fileobj=compressed, mode='w', format=tarfile.GNU_FORMAT) as tar:
            info = tarfile.TarInfo('main.py')
            info.size, info.mode, info.mtime = len(source_bytes), 0o644, 0
            tar.addfile(info, io.BytesIO(source_bytes))

# Verify
with tarfile.open(ARCHIVE) as tar:
    assert tar.getnames() == ['main.py']
    assert tar.extractfile('main.py').read() == source_bytes

print(f'SUBMISSION READY: {ARCHIVE.name} | {ARCHIVE.stat().st_size:,} bytes')
display(FileLink(str(ARCHIVE)))